violating:
import { Config, Effect, Layer, ServiceMap } from "effect"
import { drizzle, type NodePgDatabase } from "drizzle-orm/node-postgres"
import { Pool } from "pg"
import { relations } from "../schema/relations.js"

export class ReportingDatabase extends ServiceMap.Service<
  ReportingDatabase,
  NodePgDatabase & { readonly $client: Pool }
>()("@storage/ReportingDatabase") {
  static readonly layer = Layer.effect(
    ReportingDatabase,
    Effect.gen(function*() {
      const connectionString = yield* Config.string("REPORTING_DATABASE_URL")
      const pool = yield* Effect.acquireRelease(
        Effect.sync(() => new Pool({
          connectionString,
          max: 8,
          idleTimeoutMillis: 30_000
        })),
        (pool) => Effect.promise(() => pool.end())
      )

      return yield* Effect.sync(() => drizzle({
        client: pool,
        relations,
        logger: false
      }))
    })
  )
}

